	constexpr const BuiltinEffect* findBuiltinEffect(std::string_view a_name) {
		for (const auto& entry : BUILTIN_RECEIVER_EFFECTS) {
			if (entry.name == a_name) { return &entry; }
		}
		return nullptr;
	}
